// ─── constants ────────────────────────────────────────────────────────────────

const PAGE_SIZE = 5000;


const isProductResponse = (data: unknown): data is IProduct =>
  typeof data === 'object' &&
  data !== null &&
  Array.isArray((data as IProduct).records);

// ─── ProductCard (memoised) ───────────────────────────────────────────────────
// Uses flex: 1 — the virtual row controls width via display:flex on the parent.

interface IProductCardProps {
  canDelete: boolean;
  canEdit: boolean;
  currencyCode: string;
  onDelete: (re: IProductData) => void;
  onDetails: (re: IProductData) => void;
  onEdit: (re: IProductData) => void;
  onPrint: (re: IProductData) => void;
  re: IProductData;
}

// eslint-disable-next-line react/no-multi-comp
const ProductCard = React.memo(({
  canDelete,
  canEdit,
  currencyCode,
  onDelete,
  onDetails,
  onEdit,
  onPrint,
  re,
}: IProductCardProps) => (
  <Box sx={{ flex: 1, minWidth: 0 }}>
    <Card
      sx={{
        background: '#F8FAFC',
        border: '1px solid rgba(20,35,82,0.08)',
        borderTop: '0.5px solid #4f46e5',
        borderRadius: '10px',
        boxShadow: '0 1px 4px rgba(20,35,82,0.06)',
        height: '100%',
        overflow: 'hidden',
        transition: 'box-shadow 0.2s',
        '&:hover': { boxShadow: '0 4px 16px rgba(79,70,229,0.12)' },
      }}
      variant="outlined"
    >
      {re.imageUrl && (
        <Box
          alt={re.name}
          component="img"
          src={re.imageUrl}
          sx={{ height: 120, objectFit: 'cover', width: '100%' }}
        />
      )}

      <CardContent
        sx={{
          backgroundColor: re.isEnabled ? 'transparent' : 'rgba(220,38,38,0.02)',
          pb: '8px !important',
          pt: 1.5,
        }}
      >
        <Box sx={{ alignItems: 'flex-start', display: 'flex', gap: 1, justifyContent: 'space-between' }}>
          <Box sx={{ flex: 1, minWidth: 0 }}>
            {(re.name?.length ?? 0) > 16 ? (
              <Tooltip arrow title={re.name}>
                <Typography
                  sx={{
                    color: '#142352',
                    cursor: 'pointer',
                    fontSize: 14,
                    fontWeight: 700,
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap',
                  }}
                >
                  {re.name?.slice(0, 16)}…
                </Typography>
              </Tooltip>
            ) : (
              <Typography sx={{ color: '#142352', fontSize: 14, fontWeight: 700 }}>
                {re.name ?? '—'}
              </Typography>
            )}
            {(re.code?.length ?? 0) > 14 ? (
              <Tooltip arrow title={re.code}>
                <Typography sx={{ color: alpha('#142352', 0.45), cursor: 'pointer', fontSize: 11, fontWeight: 500 }}>
                  {re.code?.slice(0, 14)}…
                </Typography>
              </Tooltip>
            ) : (
              <Typography sx={{ color: alpha('#142352', 0.45), fontSize: 11, fontWeight: 500 }}>
                {re.code ?? '—'}
              </Typography>
            )}
          </Box>

          <Box
            sx={{
              background: re.isEnabled ? 'rgba(21,128,61,0.08)' : 'rgba(185,28,28,0.08)',
              border: `1px solid ${re.isEnabled ? 'rgba(21,128,61,0.2)' : 'rgba(185,28,28,0.2)'}`,
              borderRadius: '20px',
              color: re.isEnabled ? '#15803d' : '#b91c1c',
              flexShrink: 0,
              fontSize: 10,
              fontWeight: 700,
              letterSpacing: '0.3px',
              px: 1,
              py: 0.25,
            }}
          >
            {re.isEnabled ? 'Active' : 'Disabled'}
          </Box>
        </Box>

        <Box
          sx={{
            borderTop: '1px solid rgba(20,35,82,0.07)',
            display: 'flex',
            justifyContent: 'space-between',
            mt: 1.25,
            pt: 1,
          }}
        >
          <Box>
            <Typography sx={{ color: alpha('#142352', 0.4), fontSize: 10, fontWeight: 600, textTransform: 'uppercase' }}>
              Category
            </Typography>
            {(re.categoryName?.length ?? 0) > 10 ? (
              <Tooltip arrow title={re.categoryName}>
                <Typography sx={{ color: '#142352', cursor: 'pointer', fontSize: 13, fontWeight: 600 }}>
                  {re.categoryName?.slice(0, 10)}…
                </Typography>
              </Tooltip>
            ) : (
              <Typography sx={{ color: '#142352', fontSize: 13, fontWeight: 600 }}>
                {re.categoryName}
              </Typography>
            )}
          </Box>

          <Box sx={{ textAlign: 'right' }}>
            <Typography sx={{ color: alpha('#142352', 0.4), fontSize: 10, fontWeight: 600, textTransform: 'uppercase' }}>
              Price
            </Typography>
            <Typography sx={{ color: '#142352', fontSize: 14, fontWeight: 800 }}>
              {getPriceFormat(re.unitPrice, currencyCode)}
            </Typography>
          </Box>
        </Box>
      </CardContent>

      {(canEdit || canDelete) && (
        <CardActions
          sx={{
            borderTop: '1px solid rgba(20,35,82,0.08)',
            justifyContent: 'flex-end',
            pb: 1,
            pt: 0.75,
            px: 1.5,
          }}
        >
          <Stack direction="row" spacing={0.75}>
            {canEdit && (
              <Tooltip title="Print Label">
                <IconButton onClick={() => onPrint(re)} size="small" sx={{ borderRadius: '6px', height: 30, width: 30, '&:hover': { background: 'rgba(20,35,82,0.06)' } }}>
                  <PrintIcon sx={{ color: alpha('#142352', 0.55), fontSize: 15 }} />
                </IconButton>
              </Tooltip>
            )}
            <Tooltip title="Details">
              <IconButton onClick={() => onDetails(re)} size="small" sx={{ borderRadius: '6px', height: 30, width: 30, '&:hover': { background: 'rgba(20,35,82,0.06)' } }}>
                <FormatListBulletedIcon sx={{ color: alpha('#142352', 0.55), fontSize: 15 }} />
              </IconButton>
            </Tooltip>
            {canEdit && (
              <Tooltip title="Edit">
                <IconButton onClick={() => onEdit(re)} size="small" sx={{ borderRadius: '6px', height: 30, width: 30, '&:hover': { background: 'rgba(20,35,82,0.06)' } }}>
                  <EditIcon sx={{ color: alpha('#142352', 0.55), fontSize: 15 }} />
                </IconButton>
              </Tooltip>
            )}
            {canDelete && (
              <Tooltip title="Delete">
                <IconButton onClick={() => onDelete(re)} size="small" sx={{ borderRadius: '6px', height: 30, width: 30, '&:hover': { background: 'rgba(220,38,38,0.06)' } }}>
                  <DeleteIcon sx={{ color: '#DC2626', fontSize: 15 }} />
                </IconButton>
              </Tooltip>
            )}
          </Stack>
        </CardActions>
      )}
    </Card>
  </Box>
));
ProductCard.displayName = 'ProductCard';

// ─── VirtualProductGrid ───────────────────────────────────────────────────────
// Groups products into rows then virtualises the rows so only ~3× viewport
// rows are in the DOM at any time.  Tab switching is instant because only
// the visible handful of rows mount/unmount.

interface IVirtualGridProps {
  canDelete: boolean;
  canEdit: boolean;
  currencyCode: string;
  products: IProductData[];
  sentinelRef: React.RefObject<HTMLDivElement>;
  showSkeleton: boolean;
  onDelete: (re: IProductData) => void;
  onDetails: (re: IProductData) => void;
  onEdit: (re: IProductData) => void;
  onPrint: (re: IProductData) => void;
}

// eslint-disable-next-line react/no-multi-comp
const VirtualProductGrid = React.memo(({
  canDelete,
  canEdit,
  currencyCode,
  products,
  sentinelRef,
  showSkeleton,
  onDelete,
  onDetails,
  onEdit,
  onPrint,
}: IVirtualGridProps) => {
  const scrollRef = useRef<HTMLDivElement | null>(null);
  const [colCount, setColCount] = useState(4);

  useEffect(() => {
    const update = () => {
      const w = window.innerWidth;
      setColCount(w >= 1536 ? 6 : w >= 1200 ? 4 : w >= 900 ? 3 : w >= 600 ? 2 : 1);
    };
    update();
    window.addEventListener('resize', update);
    return () => window.removeEventListener('resize', update);
  }, []);

  // Scroll to top whenever the product list changes (tab / search switch)
  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = 0;
  }, [products]);

  const rows = useMemo(() => {
    const r: IProductData[][] = [];
    for (let i = 0; i < products.length; i += colCount) {
      r.push(products.slice(i, i + colCount));
    }
    return r;
  }, [products, colCount]);

  const virtualizer = useVirtualizer({
    count: rows.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 240,
    overscan: 3,
  });

  const scrollBoxSx = {
    height: 'calc(100vh - 310px)',
    overflowX: 'hidden' as const,
    overflowY: 'auto' as const,
    scrollbarWidth: 'thin' as const,
    '&::-webkit-scrollbar': { width: '4px' },
    '&::-webkit-scrollbar-thumb': {
      backgroundColor: alpha('#2563EB', 0.25),
      borderRadius: '4px',
    },
  };

  if (showSkeleton) {
    return (
      <Box sx={scrollBoxSx}>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2 }}>
          {[1, 2, 3, 4, 5, 6, 7, 8].map((i) => (
            <Box
              key={i}
              sx={{ flex: `0 0 calc(${100 / colCount}% - 12px)` }}
            >
              <Skeleton
                height={190}
                sx={{ borderRadius: '8px' }}
                variant="rectangular"
              />
            </Box>
          ))}
        </Box>
      </Box>
    );
  }

  if (products.length === 0) {
    return (
      <Box
        sx={{
          alignItems: 'center',
          background: alpha(appColors.blueGreyishLight[80], 0.04),
          border: `1px dashed ${alpha(appColors.blueGreyishLight[80], 0.25)}`,
          borderRadius: '8px',
          display: 'flex',
          flexDirection: 'column',
          gap: 1,
          py: 6,
        }}
      >
        <Inventory2OutlinedIcon sx={{ color: alpha('#142352', 0.2), fontSize: 40 }} />
        <Typography sx={{ color: alpha('#142352', 0.4), fontWeight: 600 }}>
          No products found
        </Typography>
      </Box>
    );
  }

  return (
    <Box
      ref={scrollRef}
      sx={scrollBoxSx}
    >
      <Box sx={{ height: `${virtualizer.getTotalSize()}px`, position: 'relative' }}>
        {virtualizer.getVirtualItems().map((vi) => {
          const row = rows[vi.index];
          return (
            <Box
              data-index={vi.index}
              key={vi.index}
              ref={virtualizer.measureElement}
              sx={{
                display: 'flex',
                gap: 2,
                left: 0,
                pb: 2,
                position: 'absolute',
                right: 0,
                top: 0,
                transform: `translateY(${vi.start}px)`,
              }}
            >
              {row.map((re) => (
                <ProductCard
                  canDelete={canDelete}
                  canEdit={canEdit}
                  currencyCode={currencyCode}
                  key={re.id}
                  onDelete={onDelete}
                  onDetails={onDetails}
                  onEdit={onEdit}
                  onPrint={onPrint}
                  re={re}
                />
              ))}
              {/* Spacers align last row when it has fewer than colCount cards */}
              {Array.from({ length: colCount - row.length }).map((_, idx) => (
                <Box
                  key={`pad-${idx}`}
                  sx={{ flex: 1 }}
                />
              ))}
            </Box>
          );
        })}
      </Box>
      {/* Sentinel triggers infinite-scroll page load */}
      <div
        ref={sentinelRef}
        style={{ height: 1 }}
      />
    </Box>
  );
});
VirtualProductGrid.displayName = 'VirtualProductGrid';

// ─── ProductSearchInput ───────────────────────────────────────────────────────
// Isolated so keystrokes never re-render ProductList.

// eslint-disable-next-line react/no-multi-comp
const ProductSearchInput = React.memo(({ onSearch }: { onSearch: (v: string) => void }) => {
  const [value, setValue] = React.useState('');
  const timerRef = React.useRef<ReturnType<typeof setTimeout>>();

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const v = e.target.value;
    setValue(v);
    clearTimeout(timerRef.current);
    timerRef.current = setTimeout(() => onSearch(v), 300);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      clearTimeout(timerRef.current);
      onSearch(value);
    }
  };

  React.useEffect(() => () => clearTimeout(timerRef.current), []);

  return (
    <TextField
      autoComplete="off"
      onChange={handleChange}
      onKeyDown={handleKeyDown}
      placeholder="Search by name or code…"
      size="small"
      sx={{
        width: { sm: '100%', md: 240 },
        '& .MuiOutlinedInput-input': { color: '#fff', fontSize: 13, '&::placeholder': { color: 'rgba(255,255,255,0.55)', opacity: 1 } },
        '& .MuiOutlinedInput-root': {
          backdropFilter: 'blur(8px)',
          backgroundColor: 'rgba(255,255,255,0.12)',
          borderRadius: '8px',
          height: 40,
          '& fieldset': { borderColor: 'rgba(255,255,255,0.22)' },
          '&:hover fieldset': { borderColor: 'rgba(255,255,255,0.45)' },
          '&.Mui-focused fieldset': { borderColor: 'rgba(255,255,255,0.7)' },
        },
      }}
      value={value}
    />
  );
});
ProductSearchInput.displayName = 'ProductSearchInput';

// ─── ProductList ──────────────────────────────────────────────────────────────

// eslint-disable-next-line react/no-multi-comp
const ProductList = () => {
  const { t } = useTranslation(['product']);
  const { userHasRight } = useUser();
  const { showErrorMessage, showMessage } = useNotifier();
  const [deleteProduct] = useDeleteProductMutation();

  const [open, setOpen] = useState(false);
  const [productData, setProductData] = useState<IProductData>();
  const [openDeleteProduct, setOpenDeleteProduct] = useState(false);
  const [openDetails, setOpenDetails] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const handleSearch = React.useCallback((v: string) => setSearchQuery(v), []);
  const [pageIndex, setPageIndex] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const [accProducts, setAccProducts] = useState<IProductData[]>([]);

  const [tabValue, setTabValue] = useState('All');
  const [tabPage, setTabPage] = useState(0);
  const [tabsPerPage, setTabsPerPage] = useState(8);

  const {
    data: allProductData,
    isLoading,
    isFetching,
  } = useGetAllProductQuery({
    pageIndex,
    pageSize: PAGE_SIZE,
    searchText: '',
  });

  const { data: companyData } = useGetUserQuery();

  const currencyCode = useMemo(() => {
    const userData = companyData?.data as IUserInfo | undefined;
    return userData?.company?.currencyCode ?? '';
  }, [companyData]);

  const isImageEnabled = useMemo(() => {
    type WithImage = { company?: { isImageEnabled?: boolean } };
    const raw = companyData?.data as WithImage | undefined;
    return raw?.company?.isImageEnabled ?? false;
  }, [companyData]);

  const products = useMemo(() => {
    if (
      pageIndex === 0 &&
      allProductData &&
      isProductResponse(allProductData.data)
    ) {
      return allProductData.data.records;
    }
    return accProducts;
  }, [pageIndex, allProductData, accProducts]);

  useEffect(() => {
    if (!allProductData || !isProductResponse(allProductData.data)) return;
    const items = allProductData.data.records;
    if (pageIndex === 0) setAccProducts(items);
    else setAccProducts((prev) => [...prev, ...items]);
    if (items.length < PAGE_SIZE) setHasMore(false);
  }, [allProductData, pageIndex]);


  useEffect(() => {
    const calc = () => {
      const w = window.innerWidth;
      if (w >= 1900) setTabsPerPage(14);
      else if (w >= 1600) setTabsPerPage(12);
      else if (w >= 1366) setTabsPerPage(11);
      else if (w >= 1200) setTabsPerPage(8);
      else if (w >= 900) setTabsPerPage(6);
      else setTabsPerPage(4);
    };
    calc();
    window.addEventListener('resize', calc);
    return () => window.removeEventListener('resize', calc);
  }, []);

  const sentinelRef = useRef<HTMLDivElement>(null);
  const loadingRef = useRef(false);

  useEffect(() => {
    loadingRef.current = false;
  }, [allProductData]);

  useEffect(() => {
    const node = sentinelRef.current;
    if (!node || isFetching || !hasMore) return;
    const io = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && !loadingRef.current) {
          loadingRef.current = true;
          setPageIndex((prev) => prev + 1);
        }
      },
      { rootMargin: '200px' }
    );
    io.observe(node);
    return () => io.disconnect();
  }, [isFetching, hasMore]);

  const filteredProducts = useMemo(() => {
    if (!searchQuery) return products;
    const q = searchQuery.toLowerCase();
    return products.filter(
      (p) =>
        p.name?.toLowerCase().includes(q) ||
        p.code?.toLowerCase().includes(q)
    );
  }, [products, searchQuery]);

  const groupedData = useMemo(() => {
    const g: Record<string, IProductData[]> = {};
    filteredProducts.forEach((p) => {
      const key = p.categoryName?.trim() || 'Uncategorized';
      (g[key] ||= []).push(p);
    });
    return g;
  }, [filteredProducts]);

  const sortedCategories = useMemo(
    () => ['All', ...Object.keys(groupedData).sort((a, b) => a.localeCompare(b))],
    [groupedData]
  );

  useEffect(() => {
    if (sortedCategories.length > 0 && tabValue !== 'All' && !groupedData[tabValue]) {
      setTabValue('All');
      setTabPage(0);
    }
  }, [sortedCategories, groupedData, tabValue]);

  const totalPages = Math.ceil(sortedCategories.length / tabsPerPage);

  const visibleTabs = sortedCategories.slice(
    tabPage * tabsPerPage,
    (tabPage + 1) * tabsPerPage
  );

  const activeProducts = useMemo(
    () => (tabValue === 'All' ? filteredProducts : (groupedData[tabValue] ?? [])),
    [tabValue, filteredProducts, groupedData]
  );

  const canEdit = userHasRight(Privileges.ProductEdit);
  const canDelete = userHasRight(Privileges.ProductDDelete);

  const componentRef = useRef<HTMLDivElement | null>(null);
  const handleLabelPrint = useReactToPrint({
    content: () => componentRef.current,
  });

  const handlePrintAndPrint = useCallback(
    (re: IProductData) => {
      setProductData(re);
      setTimeout(() => handleLabelPrint(), 10);
    },
    [handleLabelPrint]
  );

  const handleDetails = useCallback((re: IProductData) => {
    setProductData(re);
    setOpenDetails(true);
  }, []);

  const handleEdit = useCallback((re: IProductData) => {
    setProductData(re);
    setOpen(true);
  }, []);

  const handleDelete = useCallback((re: IProductData) => {
    setProductData(re);
    setOpenDeleteProduct(true);
  }, []);

  const handleTabChange = useCallback((_e: React.SyntheticEvent, v: string) => {
    startTransition(() => setTabValue(v));
  }, []);

  const handleTabPagePrev = () => {
    const p = tabPage - 1;
    setTabPage(p);
    setTabValue(sortedCategories[p * tabsPerPage] ?? 'All');
  };

  const handleTabPageNext = () => {
    const p = tabPage + 1;
    setTabPage(p);
    setTabValue(sortedCategories[p * tabsPerPage] ?? 'All');
  };

  const handleDeleteProduct = async (id: string) => {
    if (!id) return;
    try {
      const response = await deleteProduct(id).unwrap();
      if (response.status) showMessage(response.message);
      else showErrorMessage(response.message);
    } catch (e) {
      showErrorMessage((e as Error).message);
    }
  };

  const showSkeleton = isLoading && products.length === 0;

  return (
    <Box data-testid="product-container">
      {/* Hero banner */}
      <Box
        sx={{
          background: HEADER_GRADIENT,
          borderRadius: 2,
          color: '#fff',
          mb: 3,
          overflow: 'hidden',
          position: 'relative',
          px: { xs: 2, md: 3 },
          py: { xs: 1.5, md: 2 },
        }}
      >
        <Box
          sx={{
            background: 'rgba(255,255,255,0.07)',
            borderRadius: '50%',
            height: 220,
            inset: 'auto -60px -100px auto',
            pointerEvents: 'none',
            position: 'absolute',
            width: 220,
          }}
        />
        <Box
          sx={{
            background: 'rgba(255,255,255,0.05)',
            borderRadius: '50%',
            height: 260,
            inset: '-100px auto auto 55%',
            pointerEvents: 'none',
            position: 'absolute',
            width: 260,
          }}
        />
        <Box
          sx={{
            alignItems: { xs: 'flex-start', sm: 'center' },
            display: 'flex',
            flexDirection: { xs: 'column', sm: 'row' },
            gap: '20px',
            justifyContent: 'space-between',
            position: 'relative',
          }}
        >
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
            <Box
              sx={{
                alignItems: 'center',
                backdropFilter: 'blur(8px)',
                background: 'rgba(255,255,255,0.14)',
                border: '1px solid rgba(255,255,255,0.18)',
                borderRadius: '10px',
                display: 'flex',
                height: 44,
                justifyContent: 'center',
                width: 44,
              }}
            >
              <Inventory2OutlinedIcon sx={{ color: '#fff', fontSize: 22 }} />
            </Box>
            <Box>
              <Typography
                sx={{
                  color: '#fff',
                  fontSize: { xs: '1rem', md: '1.2rem' },
                  fontWeight: 800,
                  letterSpacing: '-0.02em',
                  lineHeight: 1.2,
                }}
              >
                {t('product:product')}
              </Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.72)', fontSize: '0.78rem' }}>
                {isLoading ? '—' : `${products.length} products`}
              </Typography>
            </Box>
          </Box>

          <Box sx={{ alignItems: 'center', display: 'flex', flexWrap: 'wrap', gap: '20px' }}>
            <ProductSearchInput onSearch={handleSearch} />

            {userHasRight(Privileges.ProductAAdd) && (
              <Button
                onClick={() => { setProductData(undefined); setOpen(true); }}
                startIcon={<AddIcon />}
                sx={{
                  background: 'linear-gradient(135deg, #2563EB 0%, #1d4ed8 100%)',
                  borderRadius: '8px',
                  boxShadow: `0 4px 14px ${alpha('#2563EB', 0.45)}`,
                  color: '#fff',
                  flexShrink: 0,
                  fontWeight: 700,
                  height: 40,
                  px: 2.5,
                  '&:hover': { background: 'linear-gradient(135deg, #1d4ed8 0%, #1e40af 100%)' },
                }}
                variant="contained"
              >
                <Box component="span" sx={{ display: { xs: 'none', md: 'inline' } }}>
                  {t('product:addProduct')}
                </Box>
              </Button>
            )}
          </Box>
        </Box>
      </Box>

      {/* Category tab bar */}
      <Box
        sx={{
          alignItems: 'center',
          background: '#F1F5F9',
          borderRadius: '12px',
          display: 'flex',
          mb: 2,
          p: 0.5,
          gap: 0.5,
        }}
      >
        {tabPage > 0 && (
          <IconButton
            onClick={handleTabPagePrev}
            size="small"
            sx={{
              background: '#fff',
              border: '1px solid #E2E8F0',
              borderRadius: '8px',
              color: '#475569',
              flexShrink: 0,
              height: 32,
              width: 32,
              '&:hover': { background: '#E2E8F0', borderColor: '#CBD5E1' },
            }}
          >
            <ArrowBackIosNewIcon sx={{ fontSize: 12 }} />
          </IconButton>
        )}

        <Tabs
          onChange={handleTabChange}
          sx={{
            flex: 1,
            minHeight: 38,
            '& .MuiTabs-flexContainer': { gap: 1 },
            '& .MuiTabs-indicator': { display: 'none' },
            '& .MuiTab-root': {
              background: 'transparent',
              border: '1px solid rgba(100,116,139,0.35)',
              borderRadius: '8px',
              color: '#64748B',
              fontSize: '0.78rem',
              fontWeight: 600,
              letterSpacing: '0.01em',
              minHeight: 36,
              px: 1.5,
              py: 0.5,
              textTransform: 'none',
              transition: 'all 0.15s',
              '&:not(.Mui-selected):hover': { background: 'transparent', borderColor: '#0F1D4D', color: '#0F1D4D' },
            },
            '& .Mui-selected': {
              background: HEADER_GRADIENT,
              border: 'none',
              boxShadow: '0 2px 8px rgba(15,29,77,0.22)',
              color: '#fff !important',
              '&:hover': { background: HEADER_GRADIENT },
            },
          }}
          value={visibleTabs.includes(tabValue) ? tabValue : false}
          variant="standard"
        >
          {visibleTabs.map((cat) => {
            const isSelected = tabValue === cat;
            const count = cat === 'All' ? products.length : (groupedData[cat]?.length ?? 0);
            const isLong = cat.length > 10;
            const displayName = isLong ? `${cat.slice(0, 9)}…` : cat;
            return (
              <Tab
                key={cat}
                label={
                  <Box sx={{ alignItems: 'center', display: 'flex', gap: 0.6 }}>
                    {isLong ? (
                      <Tooltip
                        arrow
                        title={cat}
                      >
                        <span>{displayName}</span>
                      </Tooltip>
                    ) : (
                      <span>{displayName}</span>
                    )}
                    <Box
                      component="span"
                      sx={{
                        background: isSelected ? 'rgba(255,255,255,0.22)' : 'rgba(15,29,77,0.09)',
                        borderRadius: '10px',
                        color: isSelected ? '#fff' : '#0F1D4D',
                        fontSize: '0.66rem',
                        fontWeight: 700,
                        lineHeight: 1,
                        px: 0.65,
                        py: 0.3,
                      }}
                    >
                      {count}
                    </Box>
                  </Box>
                }
                value={cat}
              />
            );
          })}
        </Tabs>

        {tabPage < totalPages - 1 && (
          <IconButton
            onClick={handleTabPageNext}
            size="small"
            sx={{
              background: '#fff',
              border: '1px solid #E2E8F0',
              borderRadius: '8px',
              color: '#475569',
              flexShrink: 0,
              height: 32,
              width: 32,
              '&:hover': { background: '#E2E8F0', borderColor: '#CBD5E1' },
            }}
          >
            <ArrowForwardIosIcon sx={{ fontSize: 12 }} />
          </IconButton>
        )}
      </Box>

      {/* Virtual product grid */}
      <VirtualProductGrid
        canDelete={canDelete}
        canEdit={canEdit}
        currencyCode={currencyCode}
        onDelete={handleDelete}
        onDetails={handleDetails}
        onEdit={handleEdit}
        onPrint={handlePrintAndPrint}
        products={activeProducts}
        sentinelRef={sentinelRef}
        showSkeleton={showSkeleton}
      />

      {open && (
        <NewProduct
          data={productData}
          handleCloseDialog={() => setOpen(false)}
          isImageEnabled={isImageEnabled}
          openModel={open}
          title={`${productData ? t('product:edit') : t('product:createNew')} ${t('product:product')}`}
        />
      )}

      {openDeleteProduct && (
        <DeletePopup
          content={t('product:confirmMessage')}
          handleCloseDelete={() => setOpenDeleteProduct(false)}
          onConfirm={async () => {
            if (productData?.id) await handleDeleteProduct(productData.id);
            setOpenDeleteProduct(false);
          }}
          open={openDeleteProduct}
          title={t('product:deleteProduct')}
        />
      )}

      {openDetails && productData && (
        <ProductListData
          currencyCode={currencyCode}
          data={productData}
          open={openDetails}
          setOpen={setOpenDetails}
        />
      )}

      <div style={{ display: 'none' }}>
        <LabelPrint
          height={25}
          id={productData?.id || ''}
          ref={componentRef}
          width={50}
        />
      </div>
    </Box>
  );
};

export default ProductList;
